CREATE TABLE expense_details(business_id INTEGER NOT NULL,journal_id INTEGER NOT NULL,category TEXT NOT NULL DEFAULT '',PRIMARY KEY(business_id,journal_id),FOREIGN KEY(business_id,journal_id) REFERENCES journals(business_id,id));
CREATE TABLE recurring_expenses(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL REFERENCES businesses(id),description TEXT NOT NULL,category TEXT NOT NULL DEFAULT '',amount INTEGER NOT NULL CHECK(amount>0 AND amount<=1000000000000),account TEXT NOT NULL,next_date TEXT NOT NULL,interval_months INTEGER NOT NULL CHECK(interval_months BETWEEN 1 AND 12),anchor_day INTEGER NOT NULL CHECK(anchor_day BETWEEN 1 AND 31),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),UNIQUE(business_id,id),FOREIGN KEY(business_id,account) REFERENCES accounts(business_id,code));
CREATE TABLE expense_attachments(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,journal_id INTEGER NOT NULL,name TEXT NOT NULL,mime TEXT NOT NULL,content BLOB NOT NULL,FOREIGN KEY(business_id,journal_id) REFERENCES journals(business_id,id));
CREATE TRIGGER expense_attachment_no_update BEFORE UPDATE ON expense_attachments BEGIN SELECT RAISE(ABORT,'attachments are immutable'); END;
CREATE TRIGGER expense_attachment_no_delete BEFORE DELETE ON expense_attachments BEGIN SELECT RAISE(ABORT,'attachments are immutable'); END;
CREATE TRIGGER expense_details_no_update BEFORE UPDATE ON expense_details BEGIN SELECT RAISE(ABORT,'expense details are immutable'); END;
CREATE TRIGGER expense_details_no_delete BEFORE DELETE ON expense_details BEGIN SELECT RAISE(ABORT,'expense details are immutable'); END;
